using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class SignalRemoveWires{
[InitializeOnLoadMethod]static void Init(){EditorApplication.delayCall+=Run;}
static void Run(){if(!File.Exists("SignalRemoveWires.request"))return;File.Delete("SignalRemoveWires.request");try{
var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scenes/Oasis/3D/Prefeb/Signal.prefab");var mesh=prefab.GetComponent<MeshFilter>().sharedMesh;var path=AssetDatabase.GetAssetPath(mesh);if(!File.Exists("SignalBackup/BeforeWireRemoval.asset"))File.Copy(path,"SignalBackup/BeforeWireRemoval.asset");var q=prefab.transform.localRotation;var v=mesh.vertices;var parts=SignalAudit.Parts(mesh);var removed=new HashSet<int>();int count=0;foreach(var part in parts){var b=new Bounds(q*v[part[0]],Vector3.zero);foreach(int i in part)b.Encapsulate(q*v[i]);if(b.size.z>7&&b.size.x<.16f&&b.size.y<.9f&&b.center.y>4.95f){count++;foreach(int i in part)removed.Add(i);}}if(count!=2)throw new Exception("Expected two wire sections, found "+count);
int before=mesh.triangles.Length/3;for(int s=0;s<mesh.subMeshCount;s++){var triangles=mesh.GetTriangles(s);var keep=new List<int>();for(int i=0;i<triangles.Length;i+=3)if(!removed.Contains(triangles[i])&&!removed.Contains(triangles[i+1])&&!removed.Contains(triangles[i+2])){keep.Add(triangles[i]);keep.Add(triangles[i+1]);keep.Add(triangles[i+2]);}mesh.SetTriangles(keep,s);}mesh.RecalculateBounds();mesh.UploadMeshData(false);EditorUtility.SetDirty(mesh);AssetDatabase.SaveAssets();SceneView.RepaintAll();File.WriteAllText("VenueLightingReview/WireRemoval.txt","SUCCESS: removed two overhead wire sections, "+(before-mesh.triangles.Length/3)+" triangles. Shared mesh updated. Pole, arm, signs, lenses and UVs preserved.");
var r=UnityEngine.Object.FindObjectsOfType<CityTrafficSignal>().FirstOrDefault();var c=UnityEngine.Object.FindObjectOfType<CityDayNightController>(true);if(r&&c){var inverse=Quaternion.Inverse(q);var target=r.transform.TransformPoint(inverse*new Vector3(0,4,-3.8f));var front=r.transform.rotation*inverse*Vector3.right;var pos=target+front*10+Vector3.up*.6f;CityLightingBuilder.Capture(c,Tuple.Create(pos,Quaternion.LookRotation(target-pos)),"Signal-No-Wires");}
}catch(Exception e){File.WriteAllText("VenueLightingReview/WireRemoval.txt","FAILED "+e);Debug.LogException(e);}}
}


